import { useState, useEffect } from "react";
import axios from "axios";

function App() {

  const [message, setMessage] = useState("");

  const [conversations, setConversations] = useState([]);

  const [currentChatId, setCurrentChatId] = useState(null);

  const [loading, setLoading] = useState(false);

  /* Load chats */

  useEffect(() => {

    const saved = localStorage.getItem("conversations");

    if (saved) {

      const parsed = JSON.parse(saved);

      setConversations(parsed);

      if (parsed.length > 0) {

        setCurrentChatId(parsed[0].id);
      }
    }

  }, []);

  /* Save chats */

  useEffect(() => {

    localStorage.setItem(
      "conversations",
      JSON.stringify(conversations)
    );

  }, [conversations]);

  /* Create New Chat */

  const createNewChat = () => {

    const newChat = {
      id: Date.now(),
      title: "New Chat",
      messages: []
    };

    setConversations((prev) => [
      newChat,
      ...prev
    ]);

    setCurrentChatId(newChat.id);
  };

  /* Current Chat */

  const currentChat = conversations.find(
    (chat) => chat.id === currentChatId
  );

  /* Send Message */

  const sendMessage = async () => {

    if (!message.trim()) return;

    if (!currentChatId) {

      createNewChat();

      return;
    }

    const userMessage = {
      role: "user",
      text: message
    };

    const updatedConversations =
      conversations.map((chat) => {

        if (chat.id === currentChatId) {

          return {
            ...chat,
            title:
              chat.messages.length === 0
                ? message
                : chat.title,

            messages: [
              ...chat.messages,
              userMessage
            ]
          };
        }

        return chat;
      });

    setConversations(updatedConversations);

    setLoading(true);

    try {

      const res = await axios.post(
        "http://127.0.0.1:8000/api/chat",
        {
          message: message
        }
      );

      const aiMessage = {
        role: "ai",
        text: res.data.response
      };

      const finalConversations =
        updatedConversations.map((chat) => {

          if (chat.id === currentChatId) {

            return {
              ...chat,
              messages: [
                ...chat.messages,
                aiMessage
              ]
            };
          }

          return chat;
        });

      setConversations(finalConversations);

    } catch (error) {

      console.log(error);
    }

    setMessage("");

    setLoading(false);
  };

  return (

    <div className="flex h-screen bg-slate-950 text-white">

      {/* Sidebar */}

      <div className="w-72 bg-slate-900 border-r border-slate-800 p-5 flex flex-col">

        <h1 className="text-2xl font-bold text-cyan-400 mb-8">
          AI College Companion
        </h1>

        <button
          onClick={createNewChat}
          className="w-full bg-cyan-500 hover:bg-cyan-600 p-3 rounded-xl font-semibold"
        >
          + New Chat
        </button>

        {/* Conversation List */}

        <div className="mt-8 overflow-y-auto space-y-3">

          {
            conversations.map((chat) => (

              <div
                key={chat.id}
                onClick={() =>
                  setCurrentChatId(chat.id)
                }
                className={`p-3 rounded-lg cursor-pointer truncate ${
                  currentChatId === chat.id
                    ? "bg-cyan-500"
                    : "bg-slate-800 hover:bg-slate-700"
                }`}
              >

                {chat.title}

              </div>

            ))
          }

        </div>

      </div>

      {/* Main Chat Area */}

      <div className="flex-1 flex flex-col">

        {/* Header */}

        <div className="p-5 border-b border-slate-800 text-2xl font-semibold text-cyan-300">
          AI Assistant
        </div>

        {/* Messages */}

        <div className="flex-1 overflow-y-auto p-6 space-y-5">

          {
            currentChat?.messages.map(
              (chat, index) => (

                <div
                  key={index}
                  className={`max-w-3xl p-4 rounded-2xl whitespace-pre-wrap leading-7 ${
                    chat.role === "user"
                      ? "bg-cyan-500 ml-auto"
                      : "bg-slate-800"
                  }`}
                >

                  {chat.text}

                </div>

              ))
          }

          {
            loading && (

              <div className="bg-slate-800 p-4 rounded-2xl w-fit animate-pulse">
                AI is thinking...
              </div>

            )
          }

        </div>

        {/* Input */}

        <div className="p-5 border-t border-slate-800 flex gap-4">

          <input
            type="text"
            placeholder="Ask anything..."
            value={message}
            onChange={(e) =>
              setMessage(e.target.value)
            }
            onKeyDown={(e) => {

              if (e.key === "Enter") {

                sendMessage();
              }
            }}
            className="flex-1 p-4 rounded-xl bg-slate-800 border border-slate-700 focus:outline-none"
          />

          <button
            onClick={sendMessage}
            className="bg-cyan-500 hover:bg-cyan-600 px-6 rounded-xl font-semibold"
          >
            Send
          </button>

        </div>

      </div>

    </div>
  );
}

export default App;
